import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import path from 'path';
import fs from 'fs';

const app = express();
app.use(express.json());

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

const SERVICE_KEYS: Record<string, string> = {
  'asset-service': requireEnv('ASSET_SERVICE_KEY'),
  'report-service': requireEnv('REPORT_SERVICE_KEY'),
};

const DOCUMENT_ROOT = '/var/documents';

interface ServiceToken {
  service: string;
  timestamp: number;
  nonce: string;
  scope: string;
}

function verifyHMAC(payload: string, signature: string, key: string): boolean {
  const expected = crypto.createHmac('sha256', key).update(payload).digest('hex');
  return crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(signature, 'hex'));
}

function decodeServiceToken(authHeader: string): ServiceToken | null {
  try {
    const [scheme, blob] = authHeader.split(' ');
    if (scheme !== 'ServiceAuth') return null;
    const [payloadB64, signature] = blob.split('.');
    const payload = Buffer.from(payloadB64, 'base64').toString('utf-8');
    const token: ServiceToken = JSON.parse(payload);
    const key = SERVICE_KEYS[token.service];
    if (!key) return null;
    if (!verifyHMAC(payloadB64, signature, key)) return null;
    if (Date.now() - token.timestamp > 30000) return null;
    return token;
  } catch {
    return null;
  }
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const authHeader = req.headers['authorization'];
  if (!authHeader || typeof authHeader !== 'string') {
    res.status(401).json({ error: 'Missing authorization' });
    return;
  }
  const token = decodeServiceToken(authHeader);
  if (!token) {
    res.status(403).json({ error: 'Invalid service token' });
    return;
  }
  (req as any).serviceToken = token;
  next();
}

function normalizePath(userPath: string): string {
  // Decode URI components that may be double-encoded
  let decoded = userPath;
  try {
    decoded = decodeURIComponent(userPath);
  } catch {
    // If decoding fails, use what we have
  }
  return decoded;
}

function scopeToAllowedPrefixes(scope: string): string[] {
  const mapping: Record<string, string[]> = {
    'documents:read': ['shared/', 'public/'],
    'documents:admin': ['shared/', 'public/', 'internal/'],
    'reports:read': ['reports/'],
  };
  return mapping[scope] || [];
}

function isWithinAllowedScope(resolvedPath: string, allowedPrefixes: string[]): boolean {
  const relative = path.relative(DOCUMENT_ROOT, resolvedPath);
  return allowedPrefixes.some(prefix => relative.startsWith(prefix));
}

app.get('/api/v1/documents/:category/*', authMiddleware, (req: Request, res: Response) => {
  const token = (req as any).serviceToken as ServiceToken;
  const allowedPrefixes = scopeToAllowedPrefixes(token.scope);

  if (allowedPrefixes.length === 0) {
    res.status(403).json({ error: 'Insufficient scope' });
    return;
  }

  const category = req.params.category;
  const filePart = req.params[0] || '';

  // Construct the logical path
  const logicalPath = `${category}/${filePart}`;

  // Normalize to handle encoded traversals
  const normalized = normalizePath(logicalPath);

  // Resolve against document root
  const resolvedPath = path.resolve(DOCUMENT_ROOT, normalized);

  // Verify the resolved path starts with document root
  if (!resolvedPath.startsWith(DOCUMENT_ROOT + '/')) {
    res.status(400).json({ error: 'Invalid path' });
    return;
  }

  // Check scope-based access
  if (!isWithinAllowedScope(resolvedPath, allowedPrefixes)) {
    res.status(403).json({ error: 'Access denied for this scope' });
    return;
  }

  // Resolve symlinks and verify real path is still within root
  try {
    const realPath = fs.realpathSync(resolvedPath);
    if (!realPath.startsWith(DOCUMENT_ROOT + '/')) {
      res.status(400).json({ error: 'Invalid path' });
      return;
    }
  } catch {
    res.status(404).json({ error: 'Document not found' });
    return;
  }

  try {
    const content = fs.readFileSync(resolvedPath, 'utf-8');
    res.json({ content, path: logicalPath });
  } catch (err) {
    res.status(404).json({ error: 'Document not found' });
  }
});

app.listen(3001, () => console.log('Document service on :3001'));

export default app;
